def largest(a, b, c):
    best = a
    if b > best:
        best = b
    if c > best:
        best = c
    return best

def count_vowels(word):
    count = 0
    for ch in word:
        if ch in "aeiou":
            count = count + 1
    return count

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result = result * i
    return result

def min_max(numbers):
    low = numbers[0]
    high = numbers[0]
    for n in numbers:
        if n < low:
            low = n
        if n > high:
            high = n
    return low, high

