def describe(name, title="Adept"):
    return f"{title} {name}"

print(describe("Mira"))

def clamp(x, low, high):
    if x < low:
        return low
    if x > high:
        return high
    return x

def repeat(text, times=2):
    parts = []
    for i in range(times):
        parts.append(text)
    return " ".join(parts)

def total_cost(prices, tax=0):
    subtotal = 0
    for p in prices:
        subtotal = subtotal + p
    return subtotal * (1 + tax / 100)
